export const MEDSHIELD_STYLE = "\n/* â”€â”€ DESIGN TOKENS â”€â”€ */\n:root {\n  --bg-base:      #EEF4F7;\n  --bg-surface:   #FFFFFF;\n  --bg-elevated:  #F4F8FA;\n  --border:       #C9DBE5;\n  --border-strong:#A9C2D2;\n  --text-primary: #13354A;\n  --text-secondary:#335F78;\n  --text-muted:   #67879A;\n  --accent:       #1CA4E8;\n  --accent-light: #DFF4FF;\n  --accent-mid:   #1585BC;\n  --amber:        #C69A2E;\n  --amber-light:  #FAF0D2;\n  --red:          #B74040;\n  --red-light:    #FEE2E2;\n  --blue:         #0E6FA6;\n  --blue-light:   #D7ECF7;\n  --shadow-sm:    0 2px 8px rgba(19,53,74,0.05);\n  --shadow-md:    0 10px 24px rgba(19,53,74,0.08);\n  --radius-sm:    6px;\n  --radius-md:    8px;\n  --radius-lg:    12px;\n  --font-display: \u0027DM Sans\u0027, \u0027Open Sans\u0027, system-ui, sans-serif;\n  --font-body:    \u0027Open Sans\u0027, system-ui, sans-serif;\n  --sidebar-expanded-w: 228px;\n  --sidebar-collapsed-w: 84px;\n  --sidebar-w:    var(--sidebar-expanded-w);\n  --transition:   0.22s ease;\n}\n\n/* â”€â”€ RESET â”€â”€ */\n*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\nhtml { font-size: 14px; }\nbody {\n  font-family: var(--font-body);\n  background: var(--bg-base);\n  color: var(--text-primary);\n  display: flex;\n  min-height: 100vh;\n  transition: background var(--transition), color var(--transition);\n}\nbody.nav-collapsed { --sidebar-w: var(--sidebar-collapsed-w); }\nbody.nav-hidden { --sidebar-w: 0px; }\nbody.nav-open { overflow: hidden; }\na { text-decoration: none; color: inherit; }\nbutton { border: none; cursor: pointer; font-family: inherit; }\n\n/* â”€â”€ SIDEBAR â”€â”€ */\n.sidebar {\n  width: var(--sidebar-w);\n  background: #12384E;\n  border-right: none;\n  box-shadow: none;\n  display: flex;\n  flex-direction: column;\n  position: fixed;\n  top: 0; left: 0; bottom: 0;\n  z-index: 100;\n  overflow: hidden;\n  transition: width var(--transition), transform var(--transition), background var(--transition);\n}\n.sidebar-brand {\n  padding: 18px 18px 16px;\n  border-bottom: 1px solid #28536B;\n}\n.brand-logo {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  min-height: 42px;\n}\n.brand-icon {\n  width: 40px; height: 40px;\n  border-radius: 12px;\n  display: flex; align-items: center; justify-content: center;\n  flex-shrink: 0;\n  overflow: hidden;\n  background: #F1F7FA;\n  box-shadow: inset 0 0 0 1px #D4E4EC;\n}\n.brand-icon img {\n  width: 100%;\n  height: 100%;\n  object-fit: contain;\n  padding: 4px;\n  display: block;\n}\n.brand-name {\n  font-family: var(--font-display);\n  font-size: 16px;\n  color: #F7FBFD;\n  line-height: 1.2;\n  font-weight: 700;\n}\n.brand-sub {\n  font-size: 10px;\n  color: #AAC5D4;\n  letter-spacing: 0.06em;\n  text-transform: uppercase;\n  margin-top: 2px;\n}\n.brand-text,\n.nav-label,\n.nav-section {\n  transition: opacity var(--transition), transform var(--transition), max-width var(--transition);\n}\n.brand-text {\n  max-width: 148px;\n  overflow: hidden;\n}\n.nav-label {\n  display: inline-block;\n  max-width: 168px;\n  overflow: hidden;\n}\n.nav {\n  flex: 1;\n  padding: 14px;\n  overflow-y: auto;\n  overflow-x: hidden;\n}\n.nav-section {\n  font-size: 10px;\n  font-weight: 500;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n  color: #89A9BB;\n  padding: 10px 10px 6px;\n}\n.nav-item {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  min-height: 40px;\n  padding: 10px 14px;\n  border-radius: 10px;\n  color: #D5E4EC;\n  font-size: 13px;\n  font-weight: 400;\n  cursor: pointer;\n  position: relative;\n  transition: all var(--transition);\n  margin-bottom: 6px;\n  white-space: nowrap;\n}\n.nav-item:hover { background: rgba(255,255,255,0.05); color: #FFFFFF; }\n.nav-item.active {\n  background: #F7FBFD;\n  color: #12384E;\n  font-weight: 500;\n  box-shadow: 0 6px 16px rgba(7,29,43,0.16);\n}\n.nav-icon { width: 16px; height: 16px; opacity: 0.7; flex-shrink: 0; }\n.nav-item.active .nav-icon { opacity: 1; }\nbody.nav-collapsed .nav-item[data-tooltip]::after {\n  content: attr(data-tooltip);\n  position: absolute;\n  left: calc(100% + 10px);\n  top: 50%;\n  transform: translateY(-50%);\n  padding: 7px 10px;\n  border-radius: 10px;\n  background: #0F2F43;\n  color: #F7FBFD;\n  font-size: 11px;\n  font-weight: 600;\n  white-space: nowrap;\n  opacity: 0;\n  pointer-events: none;\n  box-shadow: var(--shadow-md);\n  transition: opacity 0.16s ease, transform 0.16s ease;\n}\nbody.nav-collapsed .nav-item:hover::after {\n  opacity: 1;\n  transform: translateY(-50%) translateX(2px);\n}\n.sidebar-backdrop {\n  position: fixed;\n  inset: 0;\n  background: rgba(19,53,74,0.32);\n  opacity: 0;\n  pointer-events: none;\n  transition: opacity var(--transition);\n  z-index: 90;\n}\nbody.nav-open .sidebar-backdrop {\n  opacity: 1;\n  pointer-events: auto;\n}\nbody.nav-hidden .sidebar {\n  transform: translateX(-100%);\n}\nbody.nav-hidden.nav-open .sidebar {\n  width: min(286px, calc(100vw - 32px));\n  transform: translateX(0);\n}\nbody.nav-collapsed .sidebar {\n  width: var(--sidebar-collapsed-w);\n}\nbody.nav-collapsed .sidebar-brand {\n  padding-left: 22px;\n  padding-right: 22px;\n}\nbody.nav-collapsed .brand-logo {\n  justify-content: center;\n}\nbody.nav-collapsed .brand-text,\nbody.nav-collapsed .nav-label,\nbody.nav-collapsed .nav-section {\n  opacity: 0;\n  pointer-events: none;\n  transform: translateX(-8px);\n}\nbody.nav-collapsed .brand-text,\nbody.nav-collapsed .nav-label {\n  max-width: 0;\n}\nbody.nav-collapsed .nav-section {\n  height: 10px;\n  padding: 6px 0;\n  font-size: 0;\n}\nbody.nav-collapsed .nav-item {\n  width: 44px;\n  min-height: 42px;\n  height: 42px;\n  justify-content: center;\n  padding-left: 0;\n  padding-right: 0;\n  margin-left: auto;\n  margin-right: auto;\n}\n.sidebar-footer {\n  padding: 12px 14px 14px;\n  border-top: 1px solid #28536B;\n}\nbody.nav-collapsed .sidebar-footer {\n  padding-left: 10px;\n  padding-right: 10px;\n}\n.sidebar-user {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n.sidebar-avatar {\n  width: 34px;\n  height: 34px;\n  border-radius: 999px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  background: rgba(255,255,255,0.14);\n  color: #FFFFFF;\n  font-family: var(--font-display);\n  font-size: 12px;\n  font-weight: 700;\n  flex-shrink: 0;\n}\n.sidebar-user-meta {\n  min-width: 0;\n}\n.sidebar-user-name,\n.sidebar-user-role,\n.sidebar-footer-actions,\n.sidebar-footer-meta {\n  transition: opacity var(--transition), transform var(--transition), max-height var(--transition);\n}\n.sidebar-user-name {\n  font-size: 12px;\n  font-weight: 600;\n  color: #F7FBFD;\n}\n.sidebar-user-role {\n  font-size: 10px;\n  color: #AAC5D4;\n  margin-top: 2px;\n}\n.sidebar-footer-actions {\n  display: flex;\n  gap: 8px;\n  margin-top: 12px;\n}\n.sidebar-footer-btn {\n  width: 34px;\n  height: 34px;\n  border-radius: 10px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  background: rgba(255,255,255,0.08);\n  border: 1px solid rgba(255,255,255,0.12);\n  color: #D5E4EC;\n  transition: all var(--transition);\n}\n.sidebar-footer-btn:hover {\n  background: rgba(255,255,255,0.16);\n  color: #FFFFFF;\n}\n.sidebar-footer-meta {\n  margin-top: 10px;\n  font-size: 10px;\n  color: #89A9BB;\n}\nbody.nav-collapsed .sidebar-user-meta,\nbody.nav-collapsed .sidebar-footer-meta {\n  opacity: 0;\n  max-height: 0;\n  overflow: hidden;\n  transform: translateX(-6px);\n}\nbody.nav-collapsed .sidebar-footer-actions {\n  justify-content: center;\n}\n\n/* â”€â”€ MAIN â”€â”€ */\n.main {\n  margin-left: var(--sidebar-w);\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  min-height: 100vh;\n  min-width: 0;\n  transition: margin-left var(--transition);\n}\n\n/* â”€â”€ TOPBAR â”€â”€ */\n.topbar {\n  background: linear-gradient(135deg, #0E6FA6 0%, #1585BC 100%);\n  border-bottom: 1px solid #0A5D8C;\n  padding: 0 28px;\n  min-height: 62px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  position: sticky;\n  top: 0;\n  z-index: 50;\n  transition: background var(--transition), padding var(--transition);\n  box-shadow: 0 2px 14px rgba(14,111,166,0.20);\n}\n.topbar-left {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  min-width: 0;\n}\n.topbar-title-group {\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n}\n.page-title {\n  font-family: var(--font-display);\n  font-size: 16px;\n  color: #FFFFFF;\n  line-height: 1;\n  font-weight: 700;\n}\n.page-sub {\n  font-size: 11px;\n  color: #CDE5F2;\n  margin-top: 4px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.nav-toggle {\n  width: 36px;\n  height: 36px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: var(--radius-sm);\n  color: #FFFFFF;\n  background: rgba(255,255,255,0.12);\n  border: 1px solid rgba(255,255,255,0.24);\n  transition: all var(--transition);\n  flex-shrink: 0;\n}\n.nav-toggle:hover {\n  background: rgba(255,255,255,0.18);\n  border-color: rgba(255,255,255,0.34);\n}\n.nav-toggle svg { width: 18px; height: 18px; }\n.topbar-right { display: flex; align-items: center; gap: 10px; min-width: 0; }\n.topbar-badge {\n  display: flex; align-items: center; gap: 6px;\n  padding: 5px 10px;\n  background: rgba(255,255,255,0.15);\n  border: 1px solid rgba(255,255,255,0.25);\n  border-radius: 20px;\n  font-size: 11px;\n  color: #FFFFFF;\n  font-weight: 500;\n}\n.live-dot {\n  width: 6px; height: 6px;\n  background: #4FD1C8;\n  border-radius: 50%;\n  animation: pulse 2s infinite;\n}\n@keyframes pulse {\n  0%,100% { opacity: 1; transform: scale(1); }\n  50% { opacity: 0.5; transform: scale(0.8); }\n}\n.comparison-selector {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 6px 8px;\n  background: rgba(255,255,255,0.10);\n  border: 1px solid rgba(255,255,255,0.20);\n  border-radius: 6px;\n}\n.comp-mode-btn {\n  padding: 4px 10px;\n  border-radius: 4px;\n  font-size: 10px;\n  font-weight: 500;\n  background: transparent;\n  color: #B3D9F0;\n  border: 1px solid transparent;\n  transition: all var(--transition);\n}\n.comp-mode-btn.active {\n  background: rgba(255,255,255,0.24);\n  color: #FFFFFF;\n  border-color: rgba(255,255,255,0.35);\n}\n.comp-mode-btn:hover {\n  background: rgba(255,255,255,0.15);\n  color: #FFFFFF;\n}\n.year-selector {\n  display: flex; align-items: center; gap: 4px; flex-wrap: wrap;\n}\n.yr-btn {\n  padding: 4px 10px;\n  border-radius: 4px;\n  font-size: 11px;\n  font-weight: 500;\n  background: rgba(255,255,255,0.10);\n  color: #B3D9F0;\n  border: 1px solid transparent;\n  transition: all var(--transition);\n}\n.yr-btn.active {\n  background: rgba(255,255,255,0.30);\n  color: #FFFFFF;\n  border-color: rgba(255,255,255,0.40);\n}\n.yr-btn:hover {\n  background: rgba(255,255,255,0.20);\n  color: #FFFFFF;\n}\n/* â”€â”€ CONTENT â”€â”€ */\n.filterbar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 14px;\n  width: 100%;\n  max-width: 1640px;\n  margin: 0 auto;\n  padding: 16px 28px 0;\n}\n.filterbar.is-hidden {\n  display: none;\n}\n.filterbar-main {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  flex-wrap: wrap;\n}\n.filterbar-label {\n  font-size: 10px;\n  font-weight: 700;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n  color: var(--text-muted);\n}\n.filterbar .comparison-selector,\n.filterbar .year-selector {\n  min-height: 36px;\n}\n.filterbar .comparison-selector {\n  background: var(--bg-surface);\n  border-color: var(--border);\n  box-shadow: var(--shadow-sm);\n}\n.filterbar .comp-mode-btn,\n.filterbar .yr-btn {\n  color: var(--text-secondary);\n}\n.filterbar .comp-mode-btn.active,\n.filterbar .yr-btn.active {\n  background: var(--accent-light);\n  color: var(--blue);\n  border-color: rgba(28,164,232,0.26);\n}\n.filterbar .comp-mode-btn:hover,\n.filterbar .yr-btn:hover {\n  background: rgba(28,164,232,0.1);\n  color: var(--blue);\n}\n.filterbar select {\n  padding: 7px 10px;\n  border-radius: 8px;\n  border: 1px solid var(--border);\n  background: var(--bg-surface);\n  color: var(--text-primary);\n  font-size: 11px;\n  font-family: inherit;\n}\n.filterbar-note {\n  font-size: 11px;\n  color: var(--text-secondary);\n  text-align: right;\n}\n.content {\n  width: 100%;\n  max-width: 1640px;\n  margin: 0 auto;\n  padding: 24px 28px 42px;\n  flex: 1;\n}\n\n/* â”€â”€ PAGES â”€â”€ */\n.page { display: none; }\n.page.active { display: block; animation: pageFade 0.18s ease; }\n@keyframes pageFade {\n  from { opacity: 0; transform: translateY(6px); }\n  to { opacity: 1; transform: translateY(0); }\n}\n\n/* â”€â”€ KPI GRID â”€â”€ */\n.kpi-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\n  gap: 14px;\n  margin-bottom: 24px;\n}\n.kpi-card {\n  background: var(--bg-surface);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-md);\n  padding: 18px 20px;\n  box-shadow: var(--shadow-sm);\n  transition: all var(--transition);\n  position: relative;\n  overflow: hidden;\n}\n.kpi-card::before {\n  content: \u0027\u0027;\n  position: absolute;\n  top: 0; left: 0; right: 0;\n  height: 3px;\n  background: var(--kpi-accent, var(--accent));\n  border-radius: var(--radius-md) var(--radius-md) 0 0;\n}\n.kpi-label {\n  font-size: 11px;\n  font-weight: 500;\n  letter-spacing: 0.05em;\n  text-transform: uppercase;\n  color: var(--text-muted);\n  margin-bottom: 8px;\n}\n.kpi-value {\n  font-family: var(--font-display);\n  font-size: clamp(34px, 4vw, 40px);\n  color: var(--text-primary);\n  line-height: 1;\n  margin-bottom: 6px;\n  letter-spacing: -0.03em;\n}\n.kpi-sub {\n  font-size: 11px;\n  color: var(--text-secondary);\n}\n.kpi-tag {\n  display: inline-flex;\n  align-items: center;\n  gap: 3px;\n  font-size: 11px;\n  font-weight: 500;\n  padding: 2px 7px;\n  border-radius: 10px;\n}\n.kpi-tag.up { background: var(--accent-light); color: var(--accent); }\n.kpi-tag.down { background: var(--red-light); color: var(--red); }\n.kpi-tag.neutral { background: var(--amber-light); color: var(--amber); }\n\n/* â”€â”€ CHART GRID â”€â”€ */\n.chart-grid-2 {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));\n  gap: 14px;\n  margin-bottom: 14px;\n}\n.chart-grid-3 {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));\n  gap: 14px;\n  margin-bottom: 14px;\n}\n.chart-full { margin-bottom: 14px; }\n.chart-card {\n  background: var(--bg-surface);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-md);\n  padding: 22px;\n  box-shadow: var(--shadow-sm);\n  transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition), background var(--transition);\n}\n.chart-card:hover {\n  transform: translateY(-2px);\n  box-shadow: var(--shadow-md);\n  border-color: var(--border-strong);\n}\n.chart-header {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 12px;\n  margin-bottom: 16px;\n}\n.chart-title {\n  font-family: var(--font-display);\n  font-size: 15px;\n  color: var(--text-primary);\n}\n.chart-subtitle {\n  font-size: 11px;\n  color: var(--text-muted);\n  margin-top: 2px;\n}\n.chart-badge {\n  font-size: 10px;\n  font-weight: 500;\n  padding: 3px 8px;\n  border-radius: 10px;\n  background: var(--accent-light);\n  color: var(--accent);\n  letter-spacing: 0.04em;\n  text-transform: uppercase;\n}\n.chart-wrap {\n  position: relative;\n  width: 100%;\n  min-height: 180px;\n  aspect-ratio: var(--chart-ratio, 16 / 9);\n  max-height: var(--chart-max-height, 320px);\n  border-radius: 12px;\n  overflow: hidden;\n  background: linear-gradient(180deg, #FCFEFF 0%, #F3F8FB 100%);\n}\n.chart-wrap::before {\n  content: \u0027\u0027;\n  position: absolute;\n  inset: 0;\n  background: linear-gradient(90deg, rgba(223,236,244,0.4) 0%, rgba(255,255,255,0.86) 50%, rgba(223,236,244,0.4) 100%);\n  background-size: 220% 100%;\n  animation: chartShimmer 1.3s linear infinite;\n  opacity: 0;\n  pointer-events: none;\n  transition: opacity var(--transition);\n}\n.chart-wrap[data-state=\"loading\"]::before,\n.chart-wrap[data-state=\"empty\"]::before {\n  opacity: 1;\n}\n.chart-wrap[data-state=\"ready\"]::before {\n  animation: none;\n  opacity: 0;\n}\n.chart-wrap::after {\n  content: attr(data-empty-message);\n  position: absolute;\n  inset: 0;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 20px;\n  text-align: center;\n  font-size: 12px;\n  font-weight: 600;\n  color: var(--text-secondary);\n  opacity: 0;\n  pointer-events: none;\n}\n.chart-wrap[data-state=\"empty\"]::after {\n  opacity: 1;\n}\n.chart-wrap canvas {\n  width: 100% !important;\n  height: 100% !important;\n  transition: opacity 0.18s ease;\n  cursor: crosshair;\n}\n.chart-wrap[data-state=\"loading\"] canvas,\n.chart-wrap[data-state=\"empty\"] canvas {\n  opacity: 0.18;\n}\n.chart-wrap.h180 { --chart-ratio: 18 / 6; --chart-max-height: 190px; }\n.chart-wrap.h200 { --chart-ratio: 18 / 7; --chart-max-height: 210px; }\n.chart-wrap.h220 { --chart-ratio: 16 / 9; --chart-max-height: 230px; }\n.chart-wrap.h240 { --chart-ratio: 16 / 9; --chart-max-height: 250px; }\n.chart-wrap.h260 { --chart-ratio: 16 / 9; --chart-max-height: 270px; }\n.chart-wrap.h280 { --chart-ratio: 15 / 9; --chart-max-height: 290px; }\n.chart-wrap.h300 { --chart-ratio: 15 / 9; --chart-max-height: 310px; }\n@keyframes chartShimmer {\n  from { background-position: 200% 0; }\n  to { background-position: -20% 0; }\n}\n.figure-meta {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  flex-wrap: wrap;\n  margin-top: 14px;\n}\n.mini-badge {\n  display: inline-flex;\n  align-items: center;\n  padding: 4px 9px;\n  border-radius: 999px;\n  font-size: 10px;\n  font-weight: 500;\n  letter-spacing: 0.05em;\n  text-transform: uppercase;\n  background: rgba(28,164,232,0.10);\n  color: var(--blue);\n  border: 1px solid rgba(28,164,232,0.16);\n}\n.figure-note {\n  margin-top: 12px;\n  font-size: 11px;\n  line-height: 1.6;\n  color: var(--text-secondary);\n}\n.chart-legend {\n  display: flex;\n  align-items: center;\n  gap: 14px;\n  flex-wrap: wrap;\n  margin-top: 14px;\n  font-size: 11px;\n  color: var(--text-secondary);\n}\n.chart-legend-item {\n  display: inline-flex;\n  align-items: center;\n  gap: 7px;\n}\n.legend-swatch {\n  width: 10px;\n  height: 10px;\n  border-radius: 999px;\n  flex-shrink: 0;\n}\n.figure-note strong {\n  color: var(--text-primary);\n  font-weight: 500;\n}\n\n/* â”€â”€ PRODUCT TABLE â”€â”€ */\n.product-table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 12px;\n  margin-top: 12px;\n}\n.product-table th {\n  text-align: left;\n  padding: 10px 12px;\n  font-size: 10px;\n  font-weight: 500;\n  letter-spacing: 0.06em;\n  text-transform: uppercase;\n  color: var(--text-muted);\n  border-bottom: 1px solid var(--border);\n}\n.product-table th.sortable {\n  cursor: pointer;\n  user-select: none;\n}\n.th-sort {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n}\n.sort-indicator {\n  font-size: 11px;\n  color: var(--text-muted);\n}\n.product-table th.sortable.active,\n.product-table th.sortable:hover {\n  color: var(--text-primary);\n}\n.product-table th:not(:first-child) { text-align: right; }\n.product-table td {\n  padding: 11px 12px;\n  border-bottom: 1px solid var(--border);\n  color: var(--text-primary);\n}\n.product-table td:not(:first-child) { text-align: right; }\n.product-table tr:last-child td { border-bottom: none; }\n.product-table tr:hover td { background: var(--bg-base); }\n.table-empty {\n  text-align: center !important;\n  color: var(--text-secondary);\n  font-size: 12px;\n  padding: 18px 12px !important;\n}\n.abc-pill {\n  display: inline-block;\n  width: 20px; height: 20px;\n  border-radius: 50%;\n  font-size: 10px;\n  font-weight: 500;\n  line-height: 20px;\n  text-align: center;\n}\n.abc-A { background: var(--accent-light); color: var(--accent); }\n.abc-B { background: var(--amber-light); color: var(--amber); }\n.abc-C { background: var(--blue-light); color: var(--blue); }\n.prod-bar-bg {\n  height: 4px;\n  background: var(--border);\n  border-radius: 2px;\n  margin-top: 3px;\n}\n.prod-bar-fill {\n  height: 4px;\n  border-radius: 2px;\n  background: var(--accent);\n}\n\n/* â”€â”€ ALERT CARDS â”€â”€ */\n.alert-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));\n  gap: 12px;\n  margin-bottom: 14px;\n}\n.alert-hero {\n  display: grid;\n  grid-template-columns: minmax(0, 1.5fr) minmax(260px, 0.9fr);\n  gap: 14px;\n  margin-bottom: 14px;\n}\n.alert-banner {\n  background: linear-gradient(135deg, #FFF4F4 0%, #FFE4E4 100%);\n  border: 1px solid rgba(183,64,64,0.22);\n  border-left: 5px solid var(--red);\n  border-radius: 14px;\n  padding: 18px 20px;\n  box-shadow: var(--shadow-sm);\n}\n.alert-banner-kicker {\n  font-size: 10px;\n  font-weight: 700;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n  color: var(--red);\n  margin-bottom: 8px;\n}\n.alert-banner-title {\n  font-family: var(--font-display);\n  font-size: 20px;\n  line-height: 1.15;\n  color: #8E2D2D;\n}\n.alert-banner-copy {\n  margin-top: 8px;\n  font-size: 12px;\n  line-height: 1.6;\n  color: #7A4040;\n}\n.alert-banner-tags {\n  display: flex;\n  gap: 8px;\n  flex-wrap: wrap;\n  margin-top: 12px;\n}\n.alert-banner-tag {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 5px 10px;\n  border-radius: 999px;\n  background: rgba(183,64,64,0.1);\n  color: #8E2D2D;\n  font-size: 10px;\n  font-weight: 700;\n  letter-spacing: 0.04em;\n  text-transform: uppercase;\n}\n.alert-summary {\n  background: var(--bg-surface);\n  border: 1px solid var(--border);\n  border-radius: 14px;\n  padding: 16px 18px;\n  box-shadow: var(--shadow-sm);\n}\n.alert-summary-label {\n  font-size: 10px;\n  font-weight: 700;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n  color: var(--text-muted);\n  margin-bottom: 10px;\n}\n.alert-summary-row {\n  display: flex;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 10px;\n  padding: 8px 0;\n  border-bottom: 1px solid var(--border);\n}\n.alert-summary-row:last-child {\n  border-bottom: none;\n}\n.alert-summary-key {\n  font-size: 11px;\n  color: var(--text-secondary);\n}\n.alert-summary-value {\n  font-family: var(--font-display);\n  font-size: 18px;\n  color: var(--text-primary);\n}\n.alert-card {\n  background: var(--bg-surface);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-md);\n  padding: 16px;\n  box-shadow: var(--shadow-sm);\n  transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);\n  position: relative;\n  overflow: hidden;\n}\n.alert-card:hover {\n  transform: translateY(-2px);\n  box-shadow: var(--shadow-md);\n}\n.alert-card::after {\n  content: \u0027\u0027;\n  position: absolute;\n  inset: auto 0 0 0;\n  height: 3px;\n  opacity: 0.9;\n}\n.alert-card.warn { border-left: 3px solid var(--amber); }\n.alert-card.danger { border-left: 3px solid var(--red); }\n.alert-card.ok { border-left: 3px solid var(--accent); }\n.alert-card.warn::after { background: rgba(198,154,46,0.62); }\n.alert-card.danger::after { background: rgba(183,64,64,0.72); }\n.alert-card.ok::after { background: rgba(28,164,232,0.7); }\n.alert-card.primary {\n  grid-column: span 2;\n  background: linear-gradient(180deg, #FFF9F9 0%, #FFF0F0 100%);\n  border-color: rgba(183,64,64,0.24);\n}\n.alert-icon {\n  width: 36px; height: 36px;\n  border-radius: 10px;\n  display: flex; align-items: center; justify-content: center;\n  margin-bottom: 10px;\n  font-size: 16px;\n  font-weight: 700;\n}\n.alert-icon.warn-bg { background: var(--amber-light); }\n.alert-icon.danger-bg { background: var(--red-light); }\n.alert-icon.ok-bg { background: var(--accent-light); }\n.alert-title { font-size: 14px; font-weight: 700; color: var(--text-primary); margin-bottom: 4px; }\n.alert-body { font-size: 11px; color: var(--text-secondary); line-height: 1.55; max-width: 42ch; }\n.alert-tag {\n  margin-top: 10px;\n  display: inline-flex;\n  align-items: center;\n  font-size: 10px;\n  font-weight: 700;\n  padding: 4px 9px;\n  border-radius: 999px;\n  text-transform: uppercase;\n  letter-spacing: 0.06em;\n}\n.alert-tag.warn { background: var(--amber-light); color: var(--amber); }\n.alert-tag.danger { background: var(--red-light); color: var(--red); }\n.alert-tag.ok { background: var(--accent-light); color: var(--accent); }\n.alert-tag.pulse {\n  animation: alertPulse 1.8s ease-in-out infinite;\n}\n@keyframes alertPulse {\n  0%, 100% { box-shadow: 0 0 0 0 rgba(183,64,64,0.18); }\n  50% { box-shadow: 0 0 0 8px rgba(183,64,64,0); }\n}\n\n/* â”€â”€ SECTION TITLE â”€â”€ */\n.section-title {\n  font-family: var(--font-display);\n  font-size: 17px;\n  color: var(--text-primary);\n  margin-bottom: 14px;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n.section-title::after {\n  content: \u0027\u0027;\n  flex: 1;\n  height: 1px;\n  background: var(--border);\n  margin-left: 8px;\n}\n\n/* â”€â”€ FORECAST TABLE â”€â”€ */\n.forecast-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 10px 0;\n  border-bottom: 1px solid var(--border);\n}\n.forecast-row:last-child { border-bottom: none; }\n.forecast-product { font-size: 12px; color: var(--text-primary); font-weight: 500; }\n.forecast-meta { font-size: 11px; color: var(--text-muted); }\n.forecast-values { display: flex; gap: 20px; align-items: center; }\n.forecast-val { text-align: right; }\n.forecast-val .label { font-size: 10px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.05em; }\n.forecast-val .num { font-size: 13px; font-weight: 500; color: var(--text-primary); }\n.risk-pill {\n  font-size: 10px;\n  font-weight: 500;\n  padding: 3px 8px;\n  border-radius: 10px;\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n}\n.risk-high { background: var(--red-light); color: var(--red); }\n.risk-med { background: var(--amber-light); color: var(--amber); }\n.risk-low { background: var(--accent-light); color: var(--accent); }\n\n/* â”€â”€ INFO PANEL â”€â”€ */\n.info-panel {\n  background: var(--bg-surface);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-md);\n  padding: 18px 20px;\n  margin-bottom: 14px;\n  box-shadow: var(--shadow-sm);\n}\n.info-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 16px; }\n.upload-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 14px; }\n.upload-zone {\n  background: linear-gradient(180deg, #fbfdff 0%, #f1f7fa 100%);\n  border: 1px dashed var(--border-strong);\n  border-radius: 14px;\n  padding: 18px;\n}\n.upload-zone input[type=\"file\"] {\n  display: block;\n  width: 100%;\n  margin-top: 12px;\n  color: var(--text-secondary);\n}\n.upload-hint {\n  font-size: 11px;\n  color: var(--text-muted);\n  margin-top: 8px;\n}\n.upload-log {\n  margin-top: 14px;\n  padding: 12px 14px;\n  border-radius: 12px;\n  background: var(--bg-elevated);\n  border: 1px solid var(--border);\n  color: var(--text-secondary);\n  font-size: 12px;\n  min-height: 44px;\n}\n.info-item .info-label { font-size: 10px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-muted); margin-bottom: 4px; }\n.info-item .info-val { font-size: 14px; font-weight: 500; color: var(--text-primary); }\n.info-item .info-sub { font-size: 11px; color: var(--text-secondary); margin-top: 1px; }\n.hero-panel {\n  background: var(--bg-surface);\n  border: 1px solid var(--border);\n  border-radius: 18px;\n  padding: 22px 24px;\n  margin-bottom: 16px;\n  box-shadow: var(--shadow-md);\n}\n.hero-kicker {\n  font-size: 10px;\n  font-weight: 500;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n  color: var(--accent-mid);\n  margin-bottom: 8px;\n}\n.hero-title {\n  font-family: var(--font-display);\n  font-size: 24px;\n  line-height: 1.15;\n  color: var(--text-primary);\n  max-width: 820px;\n  font-weight: 700;\n}\n.hero-copy {\n  margin-top: 10px;\n  max-width: 860px;\n  font-size: 12px;\n  line-height: 1.7;\n  color: var(--text-secondary);\n}\n.hero-summary {\n  margin-top: 14px;\n  display: flex;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n.hero-tag {\n  display: inline-flex;\n  align-items: center;\n  padding: 5px 10px;\n  border-radius: 999px;\n  font-size: 10px;\n  font-weight: 600;\n  letter-spacing: 0.05em;\n  text-transform: uppercase;\n  background: rgba(28,164,232,0.1);\n  color: var(--blue);\n  border: 1px solid rgba(28,164,232,0.16);\n}\n.method-grid {\n  margin-top: 18px;\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  gap: 14px;\n}\n.method-card {\n  background: var(--bg-elevated);\n  border: 1px solid var(--border);\n  border-radius: 14px;\n  padding: 14px 15px;\n}\n.method-label {\n  font-size: 10px;\n  font-weight: 500;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n  color: var(--text-muted);\n}\n.method-value {\n  margin-top: 6px;\n  font-size: 14px;\n  font-weight: 500;\n  color: var(--text-primary);\n}\n.method-copy {\n  margin-top: 6px;\n  font-size: 11px;\n  line-height: 1.6;\n  color: var(--text-secondary);\n}\n\n@media (max-width: 1100px) {\n  .topbar {\n    gap: 10px;\n    flex-wrap: wrap;\n    padding-top: 10px;\n    padding-bottom: 10px;\n  }\n  .topbar-right {\n    margin-left: 0;\n    flex: 1 1 100%;\n    flex-wrap: wrap;\n    justify-content: flex-start;\n  }\n  .method-grid,\n  .info-grid {\n    grid-template-columns: 1fr 1fr;\n  }\n  .alert-hero {\n    grid-template-columns: 1fr;\n  }\n}\n\n@media (max-width: 760px) {\n  body { display: flex; }\n  .sidebar {\n    width: min(286px, calc(100vw - 32px));\n    transform: translateX(-100%);\n  }\n  body.nav-open .sidebar { transform: translateX(0); }\n  .main {\n    margin-left: 0;\n    width: 100%;\n  }\n  .topbar,\n  .content {\n    padding-left: 14px;\n    padding-right: 14px;\n  }\n  .topbar {\n    min-height: auto;\n    padding-top: 12px;\n    padding-bottom: 12px;\n    align-items: stretch;\n    gap: 12px;\n    flex-direction: column;\n  }\n  .topbar-left { width: 100%; }\n  .filterbar {\n    padding-left: 14px;\n    padding-right: 14px;\n    flex-direction: column;\n    align-items: stretch;\n  }\n  .filterbar-note {\n    text-align: left;\n  }\n  .chart-card,\n  .hero-panel,\n  .info-panel {\n    padding: 16px;\n  }\n  .method-grid,\n  .info-grid,\n  .alert-grid,\n  .upload-grid {\n    grid-template-columns: 1fr;\n  }\n  .alert-card.primary {\n    grid-column: auto;\n  }\n  .kpi-grid,\n  .chart-grid-2,\n  .chart-grid-3 {\n    grid-template-columns: 1fr;\n  }\n  .forecast-row,\n  .forecast-values {\n    display: block;\n  }\n  .forecast-values {\n    margin-top: 10px;\n  }\n  .forecast-val {\n    text-align: left;\n    margin-top: 8px;\n  }\n}\n\n/* â”€â”€ SCROLLBAR â”€â”€ */\n::-webkit-scrollbar { width: 4px; }\n::-webkit-scrollbar-track { background: transparent; }\n::-webkit-scrollbar-thumb { background: var(--border-strong); border-radius: 2px; }\n\n/* â”€â”€ ANIMATIONS â”€â”€ */\n.fade-in { animation: none; }\n\nhtml[data-theme=\"dark\"] {\n  --bg-base: #0E1B24;\n  --bg-surface: #132733;\n  --bg-elevated: #173240;\n  --border: #274353;\n  --border-strong: #33576B;\n  --text-primary: #E7F2F7;\n  --text-secondary: #B6CEDB;\n  --text-muted: #89A8B8;\n  --accent-light: rgba(28,164,232,0.16);\n  --amber-light: rgba(198,154,46,0.18);\n  --red-light: rgba(183,64,64,0.18);\n  --blue-light: rgba(14,111,166,0.2);\n  --shadow-sm: 0 4px 16px rgba(0,0,0,0.24);\n  --shadow-md: 0 10px 28px rgba(0,0,0,0.32);\n}\nhtml[data-theme=\"dark\"] .topbar {\n  background: linear-gradient(135deg, #0E6FA6 0%, #1174A6 100%);\n}\nhtml[data-theme=\"dark\"] .sidebar {\n  background: #0D2A3A;\n}\nhtml[data-theme=\"dark\"] .chart-wrap {\n  background: linear-gradient(180deg, #16303C 0%, #10232D 100%);\n}\n\n/* â”€â”€ RESPONSIVE helpers â”€â”€ */\n.row { display: flex; align-items: center; gap: 8px; }\n.spacer { flex: 1; }\n";

